# In demo, cols 11-12 in rows 4-6 form a 3x2 rectangle

PATTERN = 8
BACKGROUND = 9

def find_rectangular_bg_regions(grid):
    """Find maximal rectangular regions of background cells"""
    regions = []
    rows = len(grid)
    cols = len(grid[0])

    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == BACKGROUND and (r, c) not in visited:
                # Found a rectangular region - extend right and down
                region = ((r, c),)
                visited.add((r, c))

                # Extend right
                next_r = r
                next_c = c
                while next_r < rows and next_c < cols and grid[next_r][next_c] == BACKGROUND:
                    if (next_r, next_c) not in visited:
                        region += ((next_r, next_c),)
                        visited.add((next_r, next_c))
                    next_c += 1

                # Now expand vertically
                original_c = c
                next_r = r + 1
                while next_r < rows and grid[next_r][original_c] == BACKGROUND:
                    # Check if entire row segment is still background
                    row_segment_ok = True
                    for cc in range(original_c, next_c):
                        if grid[next_r][cc] != BACKGROUND:
                            row_segment_ok = False
                            break
                    if row_segment_ok:
                        for rr in range(len(region)):
                            r_base, c_base = region[rr] if isinstance(region[0], tuple) else region
                            visited.add((r_base + 1, c_base))
                        for rr in range(next_r - r):
                            for cc in range(original_c, next_c):
                                if (next_r, cc) not in visited:
                                    region += ((next_r, cc),)
                                    visited.add((next_r, cc))
                    else:
                        break
                    next_r += 1

                regions.append(region)

    return regions

